import React, { useState, useEffect } from 'react';
import Login from './pages/Login';
import Signup from './pages/Signup';
import Dashboard from './pages/Dashboard';
import { readAuth, saveAuth, clearAuth } from './utils/auth';

function App(){ 
  const [auth, setAuth] = useState(readAuth()); 
  const [view, setView] = useState(auth ? 'dashboard' : 'login'); 

  useEffect(()=> { saveAuth(auth); }, [auth]); 

  const logout = () => { clearAuth(); setAuth(null); setView('login'); }; 

  const backgroundClass = 'bg-app'; 

  // Function to Render Login/Signup View (Centered Unit)
  const renderAuthView = () => (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%' }}>
        {/* Header Title: Centered with the form */}
        <h2 style={{ 
            color: '#1A2E35', 
            fontSize: '2.5em', 
            marginBottom: 20,
            textAlign: 'center'
        }}>
            Learning Task Manager
        </h2>
        {/* Form Component */}
        {view === 'login' && <Login onLogin={(u)=>{ setAuth(u); setView('dashboard'); }} onSwitch={()=>setView('signup')} />}
        {view === 'signup' && <Signup onSignup={(u)=>{ setAuth(u); setView('dashboard'); }} onSwitch={()=>setView('login')} />}
    </div>
  );

  return (
    <div className={backgroundClass} style={{ 
      padding: 24, 
      maxWidth: 1000, 
      margin: '0 auto',
      flexGrow: 1, 
      width: '100%',
      // Ensure vertical centering when not logged in
      justifyContent: auth ? 'flex-start' : 'center', 
    }}>

      {/* Header is ONLY shown when the user is authenticated (dashboard view) */}
      {auth && (
        <header style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          width: '100%', 
          maxWidth: '952px', 
          backgroundColor: 'white', 
          borderRadius: '8px',
          boxShadow: '0 2px 8px rgba(0, 0, 0, 0.1)',
          padding: '10px 20px',
        }}>
          <h2>Learning Task Manager</h2>
          <div>
            <span style={{ marginRight: 12, color: '#4A6C80' }}>{auth.email} ({auth.role})</span>
            <button onClick={logout}>Logout</button>
          </div>
        </header>
      )}

      <main style={{ marginTop: auth ? 20 : 0, width: '100%', maxWidth: '952px', flexGrow: 1 }}>
        {/* Conditional rendering based on view */}
        {(view === 'login' || view === 'signup') ? (
            // Render the centered title + form view
            renderAuthView()
        ) : (
            // Render the dashboard (if authenticated)
            view === 'dashboard' && auth && (
                <div style={{ backgroundColor: 'white', padding: 20, borderRadius: '8px', boxShadow: '0 2px 8px rgba(0, 0, 0, 0.1)' }}>
                    <Dashboard auth={auth} />
                </div>
            )
        )}
      </main>
    </div>
  );
}

export default App;
